<section class="connect-shell panel glass"><span class="eyebrow">A TRUSTED CONNECTION</span><h1><?= e($title) ?></h1><div class="identity-preview"><?= icon('shield') ?><div><strong><?= e($connection['label']) ?></strong><small><?= e(\Chengyu\Services\OAuth::PROVIDERS[$connection['provider']]['name']) ?></small></div><span class="pill success"><?= t('Provider verified') ?></span></div>
